    14→export const Splash: React.FC<NativeStackScreenProps<Routes, "splash">> = ({
    15→  navigation,
    16→}) => {
    17→  const screenLockPin = useAtomValue(StorageAtoms.screenLockPin);
    18→  const hasSeenOnboarding = useAtomValue(StorageAtoms.hasSeenOnboarding);
    19→  const hasSeenNotificationsIntro = useAtomValue(
    20→    PushNotificationsAtoms.hasSeenNotificationsIntro,
    21→  );
    22→  const transition = useRef(
    23→    animateParallel(
    24→      { opacity: [0, 1], translateY: [40, 0] },
    25→      { duration: 200 },
    26→    ),
    27→  ).current;
    28→
    29→  useEffect(() => {
    30→    const checkAuthAndNavigate = async () => {
    31→      try {
    32→        // Check if we have stored credentials
    33→        if (MatrixService.hasStoredCredentials()) {
    34→          const sessionRestored = await MatrixService.restoreSession();
    35→          const isVerified = MatrixService.isDeviceVerified();
    36→          await MatrixService.refreshRoomList();
    37→
    38→          if (sessionRestored && !isVerified) {
    39→            navigation.replace("confirmIdentity");
    40→            return;
    41→          }
    42→
    43→          if (!hasSeenOnboarding) {
    44→            navigation.replace("onboarding");
    45→            return;
    46→          }
    47→
    48→          if (!hasSeenNotificationsIntro) {
    49→            navigation.replace("notificationsIntro");
    50→            return;
    51→          }
    52→
    53→          //If there is a screen lock pin, navigate to the verify pin screen
    54→          if (screenLockPin && sessionRestored) {
    55→            navigation.replace("verifyPin", { isSettingsScreen: false });
    56→            return;
    57→          }
    58→
    59→          if (sessionRestored) {
    60→            // Check if app was opened from a notification
    61→            const pendingRoomId = NotifeeService.consumePendingRoomId();
    62→            if (pendingRoomId) {
    63→              navigation.reset({
    64→                index: 1,
    65→                routes: [
    66→                  { name: "home" },
    67→                  { name: "room", params: { roomId: pendingRoomId } },
    68→                ],
    69→              });
    70→              return;
    71→            }
    72→
    73→            navigation.replace("home");
    74→            return;
    75→          }
    76→        }
    77→
    78→        await MatrixService.initialize(MatrixBaseURL);
    79→        navigation.replace("welcome");
    80→      } catch (error) {
    81→        console.warn("Error during auth check:", error);
    82→        navigation.replace("welcome");
    83→      }
    84→    };
    85→
    86→    transition.start(() => {
    87→      setTimeout(checkAuthAndNavigate, 2000);
    88→    });
    89→  }, [navigation, hasSeenOnboarding, screenLockPin, transition]);
    90→
    91→  return (
    92→    <ScreenLayout>
    93→      <Block
    94→        animations={transition.animations}
    95→        flex={1}
    96→        align="center"
