   102→          height={66}
   103→          style={styles.logo}
   104→        />
   105→        <Text font="Silkscreen-Regular" size={TextSize.medium}>
   106→          CLOAK
   107→        </Text>
   108→      </Block>
   109→    </ScreenLayout>
   110→  );
   111→};
