    14→export const SetUpRecoveryKey: React.FC<
    15→  NativeStackScreenProps<Routes, "setUpRecoveryKey">
    16→> = ({ navigation }) => {
    17→  const [recoveryKey, setRecoveryKey] = useState<string | null>(null);
    18→  const [isGeneratingRecoveryKey, setIsGeneratingRecoveryKey] = useState(false);
    19→  const [isLoading, setIsLoading] = useState(true);
    20→  const [recoveryState, setRecoveryState] = useState<RecoveryState>(
    21→    RecoveryState.Unknown,
