    50→  const handleGenerateRecoveryKey = async () => {
    51→    try {
    52→      setIsGeneratingRecoveryKey(true);
    53→
    54→      let key: string;
    55→
    56→      // Backup exists (whether Enabled or Incomplete)
    57→      if (recoveryState === RecoveryState.Incomplete) {
    58→        navigation.navigate("enterRecoveryKey");
    59→        return;
    60→      }
    61→
    62→      if (recoveryKeyExists) key = await MatrixService.resetRecoveryKey();
    63→      else key = await MatrixService.enableRecovery();
    64→
    65→      setRecoveryKey(key);
